from pathlib import Path
import tarfile,hashlib,json
for app in ['customer','customer-service']:
    expected=Path('apps')/app/'out'
    with tarfile.open('.sites/deploy06-artifacts/'+app+'.tar.gz') as tar:
        actual={m.name:m for m in tar.getmembers() if m.isfile() and not Path(m.name).name.startswith('._')}
        for p in expected.rglob('*'):
            if p.is_file():
                key='dist/'+p.relative_to(expected).as_posix()
                assert hashlib.sha256(p.read_bytes()).digest()==hashlib.sha256(tar.extractfile(actual[key]).read()).digest(),key
        assert not any('/.env' in k or '/apps/api/' in k or '/.git/' in k for k in actual)
        print(app+': all '+str(sum(p.is_file() for p in expected.rglob('*')))+' export file hashes match normalized dist archive; no env/backend/git files')
